
"use client";

import { useEffect, useState } from "react";
import {
  LayoutDashboard, Upload, Database, ShieldCheck, Copy,
  GitMerge, FileText, Settings, Search, Bell, ChevronDown,
  ArrowUpRight, MoreHorizontal, Plus, X, Menu, FileSpreadsheet,
  CheckCircle2, AlertCircle, RefreshCw, Download, Trash2,
  Eye, Filter, Check, ArrowRight, SlidersHorizontal,
  Clock, Table2, Activity, Server, Lock, FileCheck,
  SearchCheck, Merge, CircleCheck, CircleAlert
} from "lucide-react";
import ImportPage from "@/components/ImportPage";

type ModuleName =
  | "Overview" | "Import data" | "Data collections"
  | "Data quality" | "Duplicate detection" | "Merge records"
  | "Reports" | "Settings";

const navItems = [
  { name: "Overview" as ModuleName, icon: LayoutDashboard },
  { name: "Import data" as ModuleName, icon: Upload },
  { name: "Data collections" as ModuleName, icon: Database },
  { name: "Data quality" as ModuleName, icon: ShieldCheck },
  { name: "Duplicate detection" as ModuleName, icon: Copy },
  { name: "Merge records" as ModuleName, icon: GitMerge },
  { name: "Reports" as ModuleName, icon: FileText },
  { name: "Settings" as ModuleName, icon: Settings },
];

function BrandMark({ width = 170 }: { width?: number }) {
  return (
    <img
      src="data:image/jpeg;base64,"
      alt="Altius Fortius — Higher and Stronger"
      style={{ display: "block", width, maxWidth: "100%", height: "auto", objectFit: "contain" }}
    />
  );
}

function PageHeading({ title, description, children }: {
  title: string; description: string; children?: React.ReactNode;
}) {
  return (
    <div className="module-heading">
      <div><h1>{title}</h1><p>{description}</p></div>
      {children}
    </div>
  );
}

function Overview({ navigate }: { navigate: (name: ModuleName) => void }) {
  const [datasets, setDatasets] = useState<DatasetApiResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;

    async function loadOverview() {
      setLoading(true);
      setError("");

      try {
        const response = await fetch("/backend/datasets", {
          cache: "no-store"
        });
        const payload = await response.json();

        if (!response.ok) {
          throw new Error(
            payload?.error ||
            payload?.message ||
            `Unable to load overview (${response.status}).`
          );
        }

        if (!Array.isArray(payload)) {
          throw new Error("The datasets API returned an unexpected response.");
        }

        if (!cancelled) {
          setDatasets(payload);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Unable to load workspace data.");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    void loadOverview();
    return () => { cancelled = true; };
  }, []);

  const totalRecords = datasets.reduce(
    (total, dataset) => total + Number(dataset.totalRows || 0),
    0
  );

  const recentDatasets = [...datasets]
    .sort((a, b) => {
      const dateA = a.importedAt ? new Date(a.importedAt).getTime() : 0;
      const dateB = b.importedAt ? new Date(b.importedAt).getTime() : 0;
      return dateB - dateA;
    })
    .slice(0, 5);

  function formatDate(value: string) {
    if (!value) return "—";
    const date = new Date(value);
    return Number.isNaN(date.getTime())
      ? value
      : date.toLocaleString("en-IN", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit"
        });
  }

  return (
    <>
      <div className="page-intro">
        <div>
          <span className="date-label">WORKSPACE / OVERVIEW</span>
          <h1>Your data estate, clarified.</h1>
          <p>A live view of datasets and imported records in your workspace.</p>
        </div>
        <button className="import-button" onClick={() => navigate("Import data")}>
          <Plus size={16}/> IMPORT EXCEL DATA
        </button>
      </div>

      <section className="kpi-strip">
        <div className="kpi">
          <span>DATASETS</span>
          <strong>{loading ? "—" : datasets.length.toLocaleString("en-IN")}</strong>
          <small>Imported datasets in this workspace</small>
        </div>
        <div className="kpi">
          <span>IMPORTED RECORDS</span>
          <strong>{loading ? "—" : totalRecords.toLocaleString("en-IN")}</strong>
          <small>Based on dataset metadata</small>
        </div>
      </section>

      {error && (
        <section className="surface full-panel">
          <p className="feedback-message" style={{ color: "#b64b3d" }}>{error}</p>
        </section>
      )}

      <section className="surface full-panel">
        <div className="section-heading">
          <div>
            <h2>Recent data collections</h2>
            <p className="panel-description">Latest datasets imported into this workspace.</p>
          </div>
          <button className="secondary-button" onClick={() => navigate("Data collections")}>
            VIEW ALL DATASETS <ArrowRight size={13}/>
          </button>
        </div>

        <div className="data-table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>DATASET</th>
                <th>RECORDS</th>
                <th>COLUMNS</th>
                <th>LAST IMPORT</th>
                <th>STATUS</th>
              </tr>
            </thead>
            <tbody>
              {recentDatasets.map(dataset => (
                <tr key={dataset.id}>
                  <td>
                    <strong>{dataset.datasetName}</strong>
                    <small style={{ display: "block", marginTop: 4 }}>{dataset.originalFileName}</small>
                  </td>
                  <td>{Number(dataset.totalRows || 0).toLocaleString("en-IN")}</td>
                  <td>{dataset.totalColumns}</td>
                  <td>{formatDate(dataset.importedAt)}</td>
                  <td>
                    <span className={`status-pill ${
                      dataset.importStatus?.toLowerCase() === "imported" ? "ready" : "review"
                    }`}>
                      {dataset.importStatus || "—"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {loading && <p className="empty-state">Loading workspace data...</p>}
          {!loading && !error && recentDatasets.length === 0 && (
            <p className="empty-state">No datasets have been imported yet. Import an Excel file to get started.</p>
          )}
        </div>
      </section>

      <section className="quick-import">
        <h2>Quick import</h2>
        <p>Excel ingestion</p>
        <div className="quick-drop" onClick={() => navigate("Import data")}>
          <Upload size={24}/>
          <strong>OPEN IMPORT CENTER</strong>
          <small>Excel schema detection · Preview · Validation</small>
        </div>
        <button className="browse-button" onClick={() => navigate("Import data")}>
          GO TO DATA IMPORT <ArrowRight size={13}/>
        </button>
      </section>
    </>
  );
}

type DatasetApiResponse = {
  id: number;
  datasetName: string;
  originalFileName: string;
  tableName: string;
  totalRows: number;
  totalColumns: number;
  importStatus: string;
  importedAt: string;
};


type ColumnQualityApiResponse = {
  columnName: string;
  databaseColumnName: string;
  dataType: string;
  totalRecords: number;
  blankRecords: number;
  completeRecords: number;
  completenessPercentage: number;
  duplicateRecords: number;
  invalidRecords: number;
  validityPercentage: number;
  uniquenessPercentage: number;
};

type DataQualityApiResponse = {
  datasetId: number;
  datasetName: string;
  tableName: string;
  totalRecords: number;
  totalColumns: number;
  totalBlankValues: number;
  totalDuplicateValues: number;
  totalInvalidValues: number;
  completenessPercentage: number;
  validityPercentage: number;
  uniquenessPercentage: number;
  overallQualityScore: number;
  columns: ColumnQualityApiResponse[];
};



function CollectionsPage() {
  const [search, setSearch] = useState("");
  const [datasets, setDatasets] = useState<DatasetApiResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  async function loadDatasets() {
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/backend/datasets", {
        cache: "no-store"
      });

      const payload = await response.json();

      if (!response.ok) {
        throw new Error(
          payload?.error ||
          payload?.message ||
          `Request failed (${response.status})`
        );
      }

      if (!Array.isArray(payload)) {
        throw new Error("The datasets API returned an unexpected response.");
      }

      setDatasets(payload);
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Unable to load datasets."
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void loadDatasets();
  }, []);

  const filtered = datasets.filter((dataset) =>
    dataset.datasetName.toLowerCase().includes(search.toLowerCase()) ||
    dataset.tableName.toLowerCase().includes(search.toLowerCase()) ||
    dataset.originalFileName.toLowerCase().includes(search.toLowerCase())
  );

  function formatDate(value: string) {
    if (!value) return "—";

    const date = new Date(value);

    return Number.isNaN(date.getTime())
      ? value
      : date.toLocaleString("en-IN", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit"
        });
  }

  return (
    <>
      <PageHeading
        title="Data collections"
        description="Browse and manage your imported datasets."
      >
        <span className="record-count">
          {datasets.length} DATASETS
        </span>
      </PageHeading>

      <section className="surface full-panel">
        <div className="toolbar">
          <label className="module-search">
            <Search size={16} />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search datasets..."
            />
          </label>

          <button
            className="secondary-button"
            onClick={() => void loadDatasets()}
            disabled={loading}
          >
            <RefreshCw size={14} />
            {loading ? "Loading" : "Refresh"}
          </button>
        </div>

        {error && (
          <p className="feedback-message" style={{ color: "#b64b3d" }}>
            {error}
          </p>
        )}

        <div className="data-table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>DATASET</th>
                <th>DATABASE TABLE</th>
                <th>RECORDS</th>
                <th>COLUMNS</th>
                <th>LAST IMPORT</th>
                <th>STATUS</th>
                <th>EXPORT</th>
              </tr>
            </thead>

            <tbody>
              {filtered.map(dataset => (
                <tr key={dataset.id}>
                  <td>
                    <strong>{dataset.datasetName}</strong>
                    <small style={{ display: "block", marginTop: 4 }}>
                      {dataset.originalFileName}
                    </small>
                  </td>

                  <td>
                    <code>{dataset.tableName}</code>
                  </td>

                  <td>
                    {dataset.totalRows.toLocaleString("en-IN")}
                  </td>

                  <td>{dataset.totalColumns}</td>

                  <td>{formatDate(dataset.importedAt)}</td>

                  <td>
                    <span
                      className={`status-pill ${
                        dataset.importStatus?.toLowerCase() === "imported"
                          ? "ready"
                          : "review"
                      }`}
                    >
                      {dataset.importStatus}
                    </span>
                  </td>

                  <td>
                    <div
                      style={{
                        display: "flex",
                        gap: 8,
                        flexWrap: "wrap"
                      }}
                    >
                      <a
                        className="secondary-button"
                        href={`/backend/datasets/${dataset.id}/export/csv`}
                        title={`Download ${dataset.datasetName} as CSV`}
                        style={{ textDecoration: "none" }}
                      >
                        <Download size={14} />
                        CSV
                      </a>

                      <a
                        className="secondary-button"
                        href={`/backend/datasets/${dataset.id}/export/excel`}
                        title={`Download ${dataset.datasetName} as Excel`}
                        style={{ textDecoration: "none" }}
                      >
                        <FileSpreadsheet size={14} />
                        Excel
                      </a>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {loading && (
            <p className="empty-state">
              Loading datasets from the backend...
            </p>
          )}

          {!loading && !error && filtered.length === 0 && (
            <p className="empty-state">
              {datasets.length === 0
                ? "No datasets have been imported yet."
                : "No datasets match your search."}
            </p>
          )}
        </div>
      </section>
    </>
  );
}



function QualityPage() {
  const [datasets, setDatasets] = useState<DatasetApiResponse[]>([]);
  const [datasetId, setDatasetId] = useState("");
  const [quality, setQuality] = useState<DataQualityApiResponse | null>(null);
  const [loadingDatasets, setLoadingDatasets] = useState(true);
  const [loadingQuality, setLoadingQuality] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;

    async function loadDatasets() {
      try {
        const response = await fetch("/backend/datasets", {
          cache: "no-store",
        });

        const payload = await response.json();

        if (!response.ok) {
          throw new Error(payload?.error || "Unable to load datasets.");
        }

        if (!Array.isArray(payload)) {
          throw new Error("Unexpected datasets response.");
        }

        if (!cancelled) {
          setDatasets(payload);

          if (payload.length > 0) {
            setDatasetId(String(payload[0].id));
          }
        }
      } catch (err) {
        if (!cancelled) {
          setError(
            err instanceof Error ? err.message : "Unable to load datasets."
          );
        }
      } finally {
        if (!cancelled) setLoadingDatasets(false);
      }
    }

    void loadDatasets();

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!datasetId) {
      setQuality(null);
      return;
    }

    let cancelled = false;

    async function loadQuality() {
      setLoadingQuality(true);
      setError("");
      setQuality(null);

      try {
        const response = await fetch(
          `/backend/datasets/${datasetId}/quality`,
          { cache: "no-store" }
        );

        const payload = await response.json();

        if (!response.ok) {
          throw new Error(
            payload?.error ||
            payload?.message ||
            `Quality analysis failed (${response.status}).`
          );
        }

        if (!cancelled) {
          setQuality(payload);
        }
      } catch (err) {
        if (!cancelled) {
          setError(
            err instanceof Error
              ? err.message
              : "Unable to analyze data quality."
          );
        }
      } finally {
        if (!cancelled) setLoadingQuality(false);
      }
    }

    void loadQuality();

    return () => {
      cancelled = true;
    };
  }, [datasetId]);

  const formatNumber = (value: number) =>
    Number(value || 0).toLocaleString("en-IN");

  const metrics = quality
    ? [
        {
          label: "COMPLETENESS",
          value: quality.completenessPercentage,
          note: `${formatNumber(quality.totalBlankValues)} blank values`,
        },
        {
          label: "VALIDITY",
          value: quality.validityPercentage,
          note: `${formatNumber(quality.totalInvalidValues)} invalid values`,
        },
        {
          label: "UNIQUENESS",
          value: quality.uniquenessPercentage,
          note: `${formatNumber(quality.totalDuplicateValues)} duplicate records across columns`,
        },
      ]
    : [];

  return (
    <>
      <PageHeading
        title="Data quality"
        description="Understand completeness, validity and uniqueness across your datasets."
      />

      <section className="surface full-panel">
        <div className="section-heading">
          <div>
            <h2>Configure quality analysis</h2>
            <p className="panel-description">
              Select an imported dataset to analyze its data quality.
            </p>
          </div>
          <button
            className="secondary-button"
            onClick={() => {
              if (datasetId) {
                setDatasetId("");
                setTimeout(() => setDatasetId(datasetId), 0);
              }
            }}
            disabled={loadingQuality || !datasetId}
          >
            <RefreshCw size={14} /> Refresh
          </button>
        </div>

        <div className="form-grid">
          <label>
            SELECT DATASET
            <select
              value={datasetId}
              onChange={(e) => setDatasetId(e.target.value)}
              disabled={loadingDatasets || datasets.length === 0}
            >
              {datasets.length === 0 && (
                <option value="">
                  {loadingDatasets ? "Loading datasets..." : "No datasets found"}
                </option>
              )}

              {datasets.map((dataset) => (
                <option key={dataset.id} value={String(dataset.id)}>
                  {dataset.datasetName} · ID {dataset.id} · {dataset.totalRows} records
                </option>
              ))}
            </select>
          </label>
        </div>

        {error && (
          <p className="feedback-message" style={{ color: "#b64b3d" }}>
            {error}
          </p>
        )}
      </section>

      {loadingQuality && (
        <section className="surface full-panel">
          <p className="empty-state">Analyzing dataset quality...</p>
        </section>
      )}

      {quality && !loadingQuality && (
        <>
          <section className="kpi-strip quality-kpis">
            <div className="kpi">
              <span>OVERALL QUALITY</span>
              <strong>{quality.overallQualityScore.toFixed(2)}%</strong>
              <small>Calculated quality score</small>
            </div>

            <div className="kpi">
              <span>TOTAL RECORDS</span>
              <strong>{formatNumber(quality.totalRecords)}</strong>
              <small>{quality.totalColumns} columns analyzed</small>
            </div>

            <div className="kpi">
              <span>MISSING VALUES</span>
              <strong>{formatNumber(quality.totalBlankValues)}</strong>
              <small>Across all columns</small>
            </div>

            <div className="kpi">
              <span>INVALID VALUES</span>
              <strong>{formatNumber(quality.totalInvalidValues)}</strong>
              <small>Detected validation issues</small>
            </div>
          </section>

          <section className="surface full-panel">
            <div className="section-heading">
              <div>
                <h2>Quality overview</h2>
                <p className="panel-description">
                  {quality.datasetName} · {quality.tableName}
                </p>
              </div>
              <span className="status-pill ready">
                LIVE DATABASE RESULTS
              </span>
            </div>

            <div className="quality-metric-grid">
              {metrics.map((metric) => (
                <div className="quality-metric-card" key={metric.label}>
                  <div className="section-heading">
                    <strong>{metric.label}</strong>
                    <strong>{metric.value.toFixed(2)}%</strong>
                  </div>
                  <div className="quality-track">
                    <i style={{ width: `${Math.min(100, Math.max(0, metric.value))}%` }} />
                  </div>
                  <small>{metric.note}</small>
                </div>
              ))}
            </div>
          </section>

          <section className="surface full-panel">
            <h2>Quality by column</h2>
            <p className="panel-description">
              Completeness, duplicate counts and validity for each database column.
            </p>

            <div className="data-table-wrap">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>COLUMN</th>
                    <th>TYPE</th>
                    <th>BLANK</th>
                    <th>DUPLICATES</th>
                    <th>INVALID</th>
                    <th>COMPLETENESS</th>
                    <th>VALIDITY</th>
                    <th>UNIQUENESS</th>
                  </tr>
                </thead>

                <tbody>
                  {quality.columns.map((column) => (
                    <tr key={column.databaseColumnName}>
                      <td>
                        <strong>{column.columnName}</strong>
                        <small style={{ display: "block", marginTop: 4 }}>
                          {column.databaseColumnName}
                        </small>
                      </td>
                      <td>{column.dataType}</td>
                      <td>{formatNumber(column.blankRecords)}</td>
                      <td>{formatNumber(column.duplicateRecords)}</td>
                      <td>{formatNumber(column.invalidRecords)}</td>
                      <td>{column.completenessPercentage.toFixed(2)}%</td>
                      <td>{column.validityPercentage.toFixed(2)}%</td>
                      <td>{column.uniquenessPercentage.toFixed(2)}%</td>
                    </tr>
                  ))}
                </tbody>
              </table>

              {quality.columns.length === 0 && (
                <p className="empty-state">
                  No column quality information available.
                </p>
              )}
            </div>
          </section>
        </>
      )}

      {!loadingDatasets && datasets.length === 0 && !error && (
        <section className="surface full-panel">
          <p className="empty-state">
            Import a dataset before running quality analysis.
          </p>
        </section>
      )}
    </>
  );
}


