function DuplicatePage() {
  const [datasets, setDatasets] = useState<DuplicateDataset[]>([]);
  const [datasetId, setDatasetId] = useState("");
  const [columns, setColumns] = useState<DatasetColumnDetails[]>([]);
  const [column, setColumn] = useState("");
  const [mode, setMode] = useState("BOTH");
  const [threshold, setThreshold] = useState("0.80");
  const [exactResult, setExactResult] = useState<ExactDuplicateResult | null>(null);
  const [nearResult, setNearResult] = useState<NearDuplicateResult | null>(null);
  const [loadingDatasets, setLoadingDatasets] = useState(true);
  const [loadingColumns, setLoadingColumns] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  const selectedColumn = columns.find(item => item.databaseColumnName === column);
  const nearSupported = selectedColumn?.dataType?.toUpperCase() === "TEXT";

  useEffect(() => {
    let cancelled = false;
    async function loadDatasets() {
      setLoadingDatasets(true);
      setError("");
      try {
        const response = await fetch("/backend/datasets", { cache: "no-store" });
        const payload = await response.json();
        if (!response.ok) throw new Error(payload?.error || payload?.message || `Unable to load datasets (${response.status}).`);
        if (!Array.isArray(payload)) throw new Error("The datasets API returned an unexpected response.");
        if (!cancelled) {
          setDatasets(payload);
          if (payload.length > 0) setDatasetId(String(payload[0].id));
        }
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : "Unable to load datasets.");
      } finally {
        if (!cancelled) setLoadingDatasets(false);
      }
    }
    void loadDatasets();
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (!datasetId) { setColumns([]); setColumn(""); return; }
    let cancelled = false;
    async function loadColumns() {
      setLoadingColumns(true);
      setError(""); setNotice(""); setExactResult(null); setNearResult(null); setColumn("");
      try {
        const response = await fetch(`/backend/datasets/${datasetId}`, { cache: "no-store" });
        const payload = await response.json();
        if (!response.ok) throw new Error(payload?.error || payload?.message || `Unable to load dataset columns (${response.status}).`);
        const datasetColumns = Array.isArray(payload?.columns) ? payload.columns : [];
        if (!cancelled) {
          setColumns(datasetColumns);
          if (datasetColumns.length > 0) setColumn(datasetColumns[0].databaseColumnName);
          else setNotice("This dataset has no column metadata.");
        }
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : "Unable to load dataset columns.");
      } finally {
        if (!cancelled) setLoadingColumns(false);
      }
    }
    void loadColumns();
    return () => { cancelled = true; };
  }, [datasetId]);

  async function refreshDuplicateGroups() {
    if (!datasetId || !column) return;

    if (mode === "EXACT") {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/duplicates/exact?column=${encodeURIComponent(column)}`
      );
      setExactResult(result);
      setNearResult(null);
    } else {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/duplicates/near?column=${encodeURIComponent(column)}&threshold=${encodeURIComponent(threshold)}`
      );
      setNearResult(result);
      setExactResult(null);
    }
  }

  async function runAnalysis() {
    if (!datasetId || !column) { setError("Select a dataset and a column before running the analysis."); return; }
    if ((mode === "BOTH" || mode === "NEAR") && !nearSupported) {
      setError("Near-duplicate detection supports TEXT columns only. Choose a TEXT column or select Exact duplicates only.");
      return;
    }
    setAnalyzing(true); setError(""); setNotice(""); setExactResult(null); setNearResult(null);
    try {
      const requests: Promise<void>[] = [];
      if (mode === "BOTH" || mode === "EXACT") {
        requests.push((async () => {
          const response = await fetch(`/backend/datasets/${datasetId}/duplicates/exact?column=${encodeURIComponent(column)}`, { cache: "no-store" });
          const payload = await response.json();
          if (!response.ok) throw new Error(payload?.error || payload?.message || `Exact analysis failed (${response.status}).`);
          setExactResult(payload);
        })());
      }
      if (mode === "BOTH" || mode === "NEAR") {
        requests.push((async () => {
          const response = await fetch(`/backend/datasets/${datasetId}/duplicates/near?column=${encodeURIComponent(column)}&threshold=${encodeURIComponent(threshold)}`, { cache: "no-store" });
          const payload = await response.json();
          if (!response.ok) throw new Error(payload?.error || payload?.message || `Near analysis failed (${response.status}).`);
          setNearResult(payload);
        })());
      }
      await Promise.all(requests);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Duplicate analysis failed.");
    } finally { setAnalyzing(false); }
  }

  const hasResults = exactResult !== null || nearResult !== null;

  return (
    <>
      <PageHeading title="Duplicate detection" description="Find exact and similar records using selected columns."/>
      <section className="surface full-panel">
        <h2>Configure duplicate analysis</h2>
        <p className="panel-description">Choose one of your imported datasets and the database column you want to compare.</p>
        <div className="form-grid">
          <label>DATASET
            <select value={datasetId} onChange={e => setDatasetId(e.target.value)} disabled={loadingDatasets || datasets.length === 0}>
              {datasets.length === 0 && <option value="">{loadingDatasets ? "Loading datasets..." : "No datasets available"}</option>}
              {datasets.map(item => <option key={item.id} value={String(item.id)}>{item.datasetName} · {item.totalRows.toLocaleString("en-IN")} records</option>)}
            </select>
          </label>
          <label>COMPARE COLUMN
            <select value={column} onChange={e => { setColumn(e.target.value); setExactResult(null); setNearResult(null); setError(""); }} disabled={loadingColumns || columns.length === 0}>
              {columns.length === 0 && <option value="">{loadingColumns ? "Loading columns..." : "No columns available"}</option>}
              {columns.map(item => <option key={item.databaseColumnName} value={item.databaseColumnName}>{item.excelColumnName} ({item.databaseColumnName})</option>)}
            </select>
          </label>
          <label>MATCH TYPE
            <select value={mode} onChange={e => { setMode(e.target.value); setExactResult(null); setNearResult(null); setError(""); }}>
              <option value="BOTH">Exact and near duplicates</option>
              <option value="EXACT">Exact duplicates only</option>
              <option value="NEAR">Near duplicates only</option>
            </select>
          </label>
        </div>
        {(mode === "BOTH" || mode === "NEAR") && (
          <div className="form-grid" style={{ marginTop: 16 }}>
            <label>SIMILARITY THRESHOLD
              <select value={threshold} onChange={e => setThreshold(e.target.value)}>
                <option value="0.50">50%</option><option value="0.60">60%</option><option value="0.70">70%</option><option value="0.80">80%</option><option value="0.85">85%</option><option value="0.90">90%</option><option value="0.95">95%</option><option value="0.99">99%</option>
              </select>
            </label>
            <div><span className="field-label">COLUMN TYPE</span><p className="panel-description" style={{ marginTop: 10 }}>{selectedColumn ? selectedColumn.dataType : "Select a column"}{selectedColumn && !nearSupported ? " · Near matching requires TEXT" : ""}</p></div>
          </div>
        )}
        {error && <p className="feedback-message" style={{ color: "#b64b3d" }}>{error}</p>}
        {notice && <p className="feedback-message">{notice}</p>}
        <div className="analysis-action">
          <button className="import-button" onClick={() => void runAnalysis()} disabled={analyzing || loadingDatasets || loadingColumns || !datasetId || !column || ((mode === "BOTH" || mode === "NEAR") && !nearSupported)}>
            <SearchCheck size={16}/> {analyzing ? "ANALYZING..." : "RUN DUPLICATE ANALYSIS"}
          </button>
        </div>
      </section>

      {hasResults && (
        <section className="surface full-panel">
          <div className="section-heading"><div><h2>Analysis results</h2><p>{exactResult?.datasetName || nearResult?.datasetName} · {column}</p></div><span className="status-pill ready">LIVE DATABASE RESULTS</span></div>
          {exactResult && <>
            <h3 style={{ marginTop: 18 }}>Exact duplicates</h3>
            <div className="result-stats">
              <div><span>TOTAL RECORDS</span><strong>{exactResult.totalRecords.toLocaleString("en-IN")}</strong></div>
              <div><span>BLANK VALUES</span><strong>{exactResult.blankRecords.toLocaleString("en-IN")}</strong></div>
              <div><span>DUPLICATE GROUPS</span><strong>{exactResult.duplicateGroups.toLocaleString("en-IN")}</strong></div>
              <div><span>DUPLICATE RECORDS</span><strong>{exactResult.duplicateRecords.toLocaleString("en-IN")}</strong></div>
              <div><span>UNIQUE RECORDS</span><strong>{exactResult.uniqueRecords.toLocaleString("en-IN")}</strong></div>
            </div>
            <h3 style={{ marginTop: 22 }}>Exact duplicate groups</h3>
            {exactResult.groups.length === 0 ? <p className="empty-state">No exact duplicate groups found in this column.</p> : (
              <div className="data-table-wrap"><table className="data-table"><thead><tr><th>MATCHING VALUE</th><th>OCCURRENCES</th></tr></thead><tbody>
                {exactResult.groups.map((group, index) => <tr key={`${group.value}-${index}`}><td>{group.value}</td><td>{group.occurrences}</td></tr>)}
              </tbody></table></div>
            )}
          </>}
          {nearResult && <>
            <h3 style={{ marginTop: 26 }}>Near duplicates</h3>
            <div className="result-stats">
              <div><span>UNIQUE VALUES COMPARED</span><strong>{nearResult.totalUniqueValues.toLocaleString("en-IN")}</strong></div>
              <div><span>CANDIDATE PAIRS</span><strong>{nearResult.candidatePairs.toLocaleString("en-IN")}</strong></div>
              <div><span>THRESHOLD</span><strong>{nearResult.thresholdPercentage.toFixed(0)}%</strong></div>
            </div>
            <h3 style={{ marginTop: 22 }}>Similar value pairs</h3>
            {nearResult.matches.length === 0 ? <p className="empty-state">No near-duplicate pairs found at this threshold.</p> : (
              <div className="data-table-wrap"><table className="data-table"><thead><tr><th>VALUE 1</th><th>VALUE 2</th><th>SIMILARITY</th><th>OCCURRENCES</th></tr></thead><tbody>
                {nearResult.matches.map((match, index) => <tr key={`${match.value1}-${match.value2}-${index}`}><td>{match.value1}</td><td>{match.value2}</td><td>{match.similarityPercentage.toFixed(2)}%</td><td>{match.occurrences1} / {match.occurrences2}</td></tr>)}
              </tbody></table>
              {nearResult.candidatePairs > nearResult.matches.length && <p className="panel-description">Showing {nearResult.matches.length} of {nearResult.candidatePairs} candidate pairs. The backend limits the returned preview to 500 pairs.</p>}
              </div>
            )}
          </>}
        </section>
      )}

      <section className="surface full-panel">
        <h2>How matching works</h2>
        <div className="info-cards">
          <div><Copy/><strong>Exact duplicates</strong><p>Values that match exactly in the selected column.</p></div>
          <div><SearchCheck/><strong>Near duplicates</strong><p>Text values compared using a configurable similarity threshold.</p></div>
          <div><CircleCheck/><strong>Unique records</strong><p>Records that do not belong to an exact duplicate group.</p></div>
        </div>
      </section>
    </>
  );
}


function MergePage() {
  const [datasets, setDatasets] = useState<DatasetApiResponse[]>([]);
  const [datasetId, setDatasetId] = useState("");
  const [columns, setColumns] = useState<DatasetColumnDetails[]>([]);
  const [column, setColumn] = useState("");
  const [mode, setMode] = useState("EXACT");
  const [threshold, setThreshold] = useState("0.80");

  const [exactResult, setExactResult] = useState<MergeExactAnalysis | null>(null);
  const [nearResult, setNearResult] = useState<MergeNearAnalysis | null>(null);

  const [review, setReview] = useState<MergeReviewResponse | null>(null);
  const [selectedValue, setSelectedValue] = useState("");
  const [selectedValue2, setSelectedValue2] = useState("");

  const [preview, setPreview] = useState<MergePreviewResult | null>(null);
  const [fieldSelections, setFieldSelections] = useState<Record<string, string>>({});
  const [survivorId, setSurvivorId] = useState("");

  const [history, setHistory] = useState<MergeHistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  const selectedColumn = columns.find(
    item => item.databaseColumnName === column
  );

  const nearSupported =
    selectedColumn?.dataType?.toUpperCase() === "TEXT";

  async function apiRequest(url: string, options?: RequestInit) {
    const response = await fetch(url, {
      cache: "no-store",
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options?.headers,
      },
    });

    const payload = await response.json().catch(() => ({}));

    if (!response.ok) {
      throw new Error(
        payload?.error ||
        payload?.message ||
        `Request failed (${response.status})`
      );
    }

    return payload;
  }

  useEffect(() => {
    let cancelled = false;

    async function loadDatasets() {
      setLoading(true);
      try {
        const payload = await apiRequest("/backend/datasets");

        if (!Array.isArray(payload)) {
          throw new Error("Unexpected datasets response.");
        }

        if (!cancelled) {
          setDatasets(payload);
          if (payload.length > 0) {
            setDatasetId(String(payload[0].id));
          }
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Unable to load datasets.");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    void loadDatasets();
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (!datasetId) {
      setColumns([]);
      setColumn("");
      return;
    }

    let cancelled = false;

    async function loadColumns() {
      setError("");
      setNotice("");
      setColumns([]);
      setColumn("");
      setExactResult(null);
      setNearResult(null);
      setReview(null);
      setPreview(null);
      setHistory([]);

      try {
        const payload = await apiRequest(
          `/backend/datasets/${datasetId}`
        );

        if (!cancelled) {
          const datasetColumns = Array.isArray(payload.columns)
            ? payload.columns
            : [];

          setColumns(datasetColumns);

          if (datasetColumns.length > 0) {
            setColumn(datasetColumns[0].databaseColumnName);
          }
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Unable to load columns.");
        }
      }
    }

    void loadColumns();
    return () => { cancelled = true; };
  }, [datasetId]);

  async function refreshDuplicateGroups() {
    if (!datasetId || !column) return;

    if (mode === "EXACT") {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/duplicates/exact?column=${encodeURIComponent(column)}`
      );
      setExactResult(result);
      setNearResult(null);
    } else {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/duplicates/near?column=${encodeURIComponent(column)}&threshold=${encodeURIComponent(threshold)}`
      );
      setNearResult(result);
      setExactResult(null);
    }
  }

  async function runAnalysis() {
    if (!datasetId || !column) {
      setError("Select a dataset and column first.");
      return;
    }

    if (mode === "NEAR" && !nearSupported) {
      setError("Near duplicate review requires a TEXT column.");
      return;
    }

    setAnalyzing(true);
    setError("");
    setNotice("");
    setExactResult(null);
    setNearResult(null);
    setReview(null);
    setPreview(null);
    setSelectedValue("");
    setSelectedValue2("");

    try {
      if (mode === "EXACT") {
        const result = await apiRequest(
          `/backend/datasets/${datasetId}/duplicates/exact?column=${encodeURIComponent(column)}`
        );
        setExactResult(result);
      } else {
        const result = await apiRequest(
          `/backend/datasets/${datasetId}/duplicates/near?column=${encodeURIComponent(column)}&threshold=${encodeURIComponent(threshold)}`
        );
        setNearResult(result);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Duplicate analysis failed.");
    } finally {
      setAnalyzing(false);
    }
  }

  async function loadExactRecords(value: string) {
    setLoading(true);
    setError("");
    setNotice("");
    setReview(null);
    setPreview(null);
    setSelectedValue(value);

    try {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/duplicates/records?column=${encodeURIComponent(column)}&value=${encodeURIComponent(value)}`
      );

      setReview(result);
      const newest = getNewestRecord(result.records || []);
      setSurvivorId(newest ? String(newest.id) : "");
      setFieldSelections({});
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to load duplicate records.");
    } finally {
      setLoading(false);
    }
  }

  async function loadNearRecords(pair: MergeNearPair) {
    setLoading(true);
    setError("");
    setNotice("");
    setReview(null);
    setPreview(null);
    setSelectedValue(pair.value1);
    setSelectedValue2(pair.value2);

    try {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/duplicates/near/records?column=${encodeURIComponent(column)}&value1=${encodeURIComponent(pair.value1)}&value2=${encodeURIComponent(pair.value2)}&threshold=${encodeURIComponent(threshold)}`
      );

      setReview(result);
      const newest = getNewestRecord(result.records || []);
      setSurvivorId(newest ? String(newest.id) : "");
      setFieldSelections({});
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to load similar records.");
    } finally {
      setLoading(false);
    }
  }

  function getRecordId(record: Record<string, unknown>) {
    return Number(record.id);
  }

  function getRecordTimestamp(record: Record<string, unknown>) {
    const value = record.created_at ?? record.createdAt;
    if (value == null || value === "") return Number.NaN;
    const parsed = new Date(String(value)).getTime();
    return Number.isFinite(parsed) ? parsed : Number.NaN;
  }

  function getNewestRecord(records: Record<string, unknown>[]) {
    return [...records].sort((a, b) => {
      const dateA = getRecordTimestamp(a);
      const dateB = getRecordTimestamp(b);
      if (Number.isFinite(dateA) && Number.isFinite(dateB) && dateA !== dateB) {
        return dateB - dateA;
      }
      if (Number.isFinite(dateA) !== Number.isFinite(dateB)) {
        return Number.isFinite(dateA) ? -1 : 1;
      }
      return getRecordId(b) - getRecordId(a);
    })[0];
  }

  async function createMergePreview() {
    if (!review || review.records.length < 2) {
      setError("At least two records are required for merging.");
      return;
    }

    const ids = review.records.map(getRecordId);

    if (ids.some(id => !Number.isFinite(id) || id <= 0)) {
      setError("The backend response does not contain valid record IDs.");
      return;
    }

    const body = {
      recordIds: ids,
      matchingColumn: column,
      matchingValue: selectedValue,
      mergeMode: mode,
      matchingValue2: mode === "NEAR" ? selectedValue2 : null,
      similarityThreshold: mode === "NEAR" ? Number(threshold) : null,
    };

    setLoading(true);
    setError("");
    setNotice("");
    setPreview(null);

    try {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/merge/preview`,
        {
          method: "POST",
          body: JSON.stringify(body),
        }
      );

      setPreview(result);

      
const initialSelections: Record<string, string> = {};

result.fields.forEach((field: MergePreviewField) => {
  if (field.hasConflict) {
    initialSelections[field.fieldName] =
      field.suggestedValue ??
      field.availableValues[0] ??
      "";
  }
});

setFieldSelections(initialSelections);


      setNotice("Merge preview loaded. Review the selected values before executing.");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to create merge preview.");
    } finally {
      setLoading(false);
    }
  }

  async function executeMerge() {
    if (!review || !preview || !survivorId) {
      setError("Create a preview and confirm the automatically selected survivor record.");
      return;
    }

    const ids = review.records.map(getRecordId);

    if (!ids.includes(Number(survivorId))) {
      setError("The survivor record must belong to the selected duplicate group.");
      return;
    }

    const body = {
      recordIds: ids,
      survivorRecordId: Number(survivorId),
      fieldSelections,
      matchingColumn: column,
      matchingValue: selectedValue,
      mergeMode: mode,
      matchingValue2: mode === "NEAR" ? selectedValue2 : null,
      similarityThreshold: mode === "NEAR" ? Number(threshold) : null,
    };

    setLoading(true);
    setError("");
    setNotice("");

    try {
      const result: MergeExecuteResult = await apiRequest(
        `/backend/datasets/${datasetId}/merge/execute`,
        {
          method: "POST",
          body: JSON.stringify(body),
        }
      );

      setNotice(
        `Merge completed. Operation ID: ${result.mergeOperationId}. ${result.message}`
      );

      setReview(null);
      setPreview(null);
      setSelectedValue("");
      setSelectedValue2("");
      setSurvivorId("");
      setFieldSelections({});

      let refreshFailed = false;
      try {
        await refreshDuplicateGroups();
      } catch (refreshErr) {
        refreshFailed = true;
        setError(
          refreshErr instanceof Error
            ? `Merge succeeded, but duplicate groups could not be refreshed: ${refreshErr.message}`
            : "Merge succeeded, but duplicate groups could not be refreshed."
        );
      }

      await loadHistory();

      if (!refreshFailed) {
        setNotice(
          `Merge completed. Operation ID: ${result.mergeOperationId}. Remaining duplicate groups have been refreshed.`
        );
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Merge execution failed.");
    } finally {
      setLoading(false);
    }
  }

  async function loadHistory() {
    if (!datasetId) return;

    setLoading(true);
    setError("");

    try {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/merge/history`
      );

      setHistory(Array.isArray(result) ? result : []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to load merge history.");
    } finally {
      setLoading(false);
    }
  }

  async function undoMerge(operationId: number) {
    const confirmed = window.confirm(
      "Undo this merge? Only the latest completed merge can be undone."
    );

    if (!confirmed) return;

    setLoading(true);
    setError("");
    setNotice("");

    try {
      const result = await apiRequest(
        `/backend/datasets/${datasetId}/merge/${operationId}/undo`,
        { method: "POST" }
      );

      setNotice(result.message || "Merge successfully reversed.");
      await refreshDuplicateGroups();
      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to undo merge.");
    } finally {
      setLoading(false);
    }
  }

  const selectedDataset = datasets.find(
    item => String(item.id) === datasetId
  );

  return (
    <>
      <PageHeading
        title="Merge records"
        description="Review duplicate records, choose field values and safely consolidate records."
      />

      <section className="surface full-panel">
        <h2>Configure merge analysis</h2>
        <p className="panel-description">
          Select a dataset, matching column and duplicate type.
        </p>

        <div className="form-grid">
          <label>
            DATASET
            <select
              value={datasetId}
              onChange={e => setDatasetId(e.target.value)}
              disabled={loading || datasets.length === 0}
            >
              {datasets.map(item => (
                <option key={item.id} value={String(item.id)}>
                  {item.datasetName} · {item.totalRows} records
                </option>
              ))}
            </select>
          </label>

          <label>
            MATCHING COLUMN
            <select
              value={column}
              onChange={e => {
                setColumn(e.target.value);
                setExactResult(null);
                setNearResult(null);
                setReview(null);
                setPreview(null);
              }}
            >
              {columns.map(item => (
                <option
                  key={item.databaseColumnName}
                  value={item.databaseColumnName}
                >
                  {item.excelColumnName} ({item.databaseColumnName})
                </option>
              ))}
            </select>
          </label>

          <label>
            MATCH TYPE
            <select
              value={mode}
              onChange={e => {
                setMode(e.target.value);
                setExactResult(null);
                setNearResult(null);
                setReview(null);
                setPreview(null);
              }}
            >
              <option value="EXACT">Exact duplicates</option>
              <option value="NEAR">Near duplicates</option>
            </select>
          </label>
        </div>

        {mode === "NEAR" && (
          <div className="form-grid" style={{ marginTop: 16 }}>
            <label>
              SIMILARITY THRESHOLD
              <select
                value={threshold}
                onChange={e => setThreshold(e.target.value)}
              >
                <option value="0.50">50%</option>
                <option value="0.60">60%</option>
                <option value="0.70">70%</option>
                <option value="0.80">80%</option>
                <option value="0.85">85%</option>
                <option value="0.90">90%</option>
                <option value="0.95">95%</option>
                <option value="0.99">99%</option>
              </select>
            </label>
            <div>
              <span className="field-label">COLUMN TYPE</span>
              <p className="panel-description" style={{ marginTop: 10 }}>
                {selectedColumn?.dataType || "Select a column"}
                {!nearSupported ? " · Near matching requires TEXT" : ""}
              </p>
            </div>
          </div>
        )}

        {error && (
          <p className="feedback-message" style={{ color: "#b64b3d" }}>
            {error}
          </p>
        )}

        {notice && <p className="feedback-message">{notice}</p>}

        <div className="analysis-action">
          <button
            className="import-button"
            onClick={() => void runAnalysis()}
            disabled={
              analyzing ||
              loading ||
              !datasetId ||
              !column ||
              (mode === "NEAR" && !nearSupported)
            }
          >
            <SearchCheck size={16} />
            {analyzing ? "ANALYZING..." : "FIND DUPLICATE GROUPS"}
          </button>
        </div>
      </section>

      {selectedDataset && (
        <section className="surface full-panel">
          <div className="section-heading">
            <div>
              <h2>Duplicate groups</h2>
              <p className="panel-description">
                {selectedDataset.datasetName} · {column}
              </p>
            </div>
            <span className="status-pill ready">LIVE DATABASE RESULTS</span>
          </div>

          {exactResult && (
            <>
              <div className="result-stats">
                <div>
                  <span>TOTAL RECORDS</span>
                  <strong>{exactResult.totalRecords}</strong>
                </div>
                <div>
                  <span>DUPLICATE GROUPS</span>
                  <strong>{exactResult.duplicateGroups}</strong>
                </div>
                <div>
                  <span>DUPLICATE RECORDS</span>
                  <strong>{exactResult.duplicateRecords}</strong>
                </div>
              </div>

              <div className="data-table-wrap">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>MATCHING VALUE</th>
                      <th>OCCURRENCES</th>
                      <th>ACTION</th>
                    </tr>
                  </thead>
                  <tbody>
                    {exactResult.groups.map((group, index) => (
                      <tr key={`${group.value}-${index}`}>
                        <td>{group.value}</td>
                        <td>{group.occurrences}</td>
                        <td>
                          <button
                            className="secondary-button"
                            onClick={() => void loadExactRecords(group.value)}
                            disabled={loading}
                          >
                            <Eye size={14} /> Review records
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {exactResult.groups.length === 0 && (
                  <p className="empty-state">No exact duplicate groups found.</p>
                )}
              </div>
            </>
          )}

          {nearResult && (
            <>
              <div className="result-stats">
                <div>
                  <span>UNIQUE VALUES</span>
                  <strong>{nearResult.totalUniqueValues}</strong>
                </div>
                <div>
                  <span>CANDIDATE PAIRS</span>
                  <strong>{nearResult.candidatePairs}</strong>
                </div>
                <div>
                  <span>THRESHOLD</span>
                  <strong>{nearResult.thresholdPercentage}%</strong>
                </div>
              </div>

              <div className="data-table-wrap">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>VALUE 1</th>
                      <th>VALUE 2</th>
                      <th>SIMILARITY</th>
                      <th>ACTION</th>
                    </tr>
                  </thead>
                  <tbody>
                    {nearResult.matches.map((pair, index) => (
                      <tr key={`${pair.value1}-${pair.value2}-${index}`}>
                        <td>{pair.value1}</td>
                        <td>{pair.value2}</td>
                        <td>{pair.similarityPercentage.toFixed(2)}%</td>
                        <td>
                          <button
                            className="secondary-button"
                            onClick={() => void loadNearRecords(pair)}
                            disabled={loading}
                          >
                            <Eye size={14} /> Review records
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {nearResult.matches.length === 0 && (
                  <p className="empty-state">No near duplicate pairs found.</p>
                )}
              </div>
            </>
          )}
        </section>
      )}

      {review && (
        <section className="surface full-panel">
          <h2>Review records before merging</h2>
          <p className="panel-description">
            {review.matchingRecords} matching records found.
            {review.truncated ? " The backend response is truncated; merging is disabled until all records can be reviewed." : ""}
          </p>

          <div className="data-table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>RECORD ID</th>
                  {Object.keys(review.records[0] || {})
                    .filter(key => key !== "id")
                    .map(key => <th key={key}>{key.toUpperCase()}</th>)}
                </tr>
              </thead>
              <tbody>
                {review.records.map((record, index) => (
                  <tr key={String(record.id ?? index)}>
                    <td>{String(record.id ?? "—")}</td>
                    {Object.keys(review.records[0] || {})
                      .filter(key => key !== "id")
                      .map(key => (
                        <td key={key}>
                          {record[key] == null ? "—" : String(record[key])}
                        </td>
                      ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="form-grid" style={{ marginTop: 20 }}>
            <label>
              SURVIVING RECORD · NEWEST BY DEFAULT
              <select
                value={survivorId}
                onChange={e => setSurvivorId(e.target.value)}
              >
                <option value="">Select a survivor record</option>
                {review.records.map((record, index) => (
                  <option
                    key={String(record.id ?? index)}
                    value={String(record.id)}
                  >
                    Record #{String(record.id)}
                  </option>
                ))}
              </select>
            </label>
          </div>

          <div className="analysis-action">
            <button
              className="import-button"
              onClick={() => void createMergePreview()}
              disabled={
                loading ||
                review.records.length < 2 ||
                Boolean(review.truncated) ||
                !survivorId
              }
            >
              <Eye size={16} /> PREVIEW MERGE
            </button>
          </div>
        </section>
      )}

      {preview && review && (
        <section className="surface full-panel">
          <h2>Consolidated record preview</h2>
          <p className="panel-description">
            The newest record is selected as the survivor by default. Conflicting fields use the newest non-blank value; you can override both before execution.
          </p>

          {preview.fields.map(field => (
            <div
              key={field.fieldName}
              className="quality-row"
              style={{ gridTemplateColumns: "1fr 2fr" }}
            >
              <div>
                <strong>{field.fieldName}</strong>
                {field.hasConflict && (
                  <small style={{ display: "block" }}>Conflicting values</small>
                )}
              </div>

              <select
                value={fieldSelections[field.fieldName] ?? ""}
                onChange={e =>
                  setFieldSelections(old => ({
                    ...old,
                    [field.fieldName]: e.target.value,
                  }))
                }
              >
                {field.availableValues.map((value, index) => (
                  <option key={`${value}-${index}`} value={value}>
                    {value === "" ? "(Blank)" : value}
                  </option>
                ))}
              </select>
            </div>
          ))}

          <div className="info-strip">
            <AlertCircle size={17} />
            <span>
              This action changes database records. Review the survivor and
              selected field values before executing.
            </span>
          </div>

          <div className="analysis-action">
            <button
              className="import-button"
              onClick={() => void executeMerge()}
              disabled={loading}
            >
              <Merge size={16} />
              {loading ? "PROCESSING..." : "EXECUTE MERGE"}
            </button>
          </div>
        </section>
      )}

      <section className="surface full-panel">
        <div className="section-heading">
          <div>
            <h2>Merge history</h2>
            <p className="panel-description">
              Review completed and reversed merge operations.
            </p>
          </div>
          <button
            className="secondary-button"
            onClick={() => void loadHistory()}
            disabled={loading || !datasetId}
          >
            <RefreshCw size={14} /> LOAD HISTORY
          </button>
        </div>

        <div className="data-table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>OPERATION ID</th>
                <th>SURVIVOR ID</th>
                <th>STATUS</th>
                <th>CREATED AT</th>
                <th>ACTION</th>
              </tr>
            </thead>
            <tbody>
              {history.map(item => (
                <tr key={item.mergeOperationId}>
                  <td>{item.mergeOperationId}</td>
                  <td>{item.survivorRecordId}</td>
                  <td>
                    <span className={`status-pill ${item.status === "COMPLETED" ? "ready" : "review"}`}>
                      {item.status}
                    </span>
                  </td>
                  <td>
                    {item.createdAt
                      ? new Date(item.createdAt).toLocaleString("en-IN")
                      : "—"}
                  </td>
                  <td>
                    {item.status === "COMPLETED" ? (
                      <button
                        className="secondary-button"
                        onClick={() => void undoMerge(item.mergeOperationId)}
                        disabled={loading}
                      >
                        <RefreshCw size={14} /> Undo
                      </button>
                    ) : "—"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {history.length === 0 && (
            <p className="empty-state">
              No merge history loaded. Select LOAD HISTORY to retrieve it.
            </p>
          )}
        </div>
      </section>
    </>
  );
}


function ReportsPage() {
  const [report, setReport] = useState("Duplicate analysis report");
  const [datasets, setDatasets] = useState<DatasetApiResponse[]>([]);
  const [datasetId, setDatasetId] = useState("");
  const [columns, setColumns] = useState<DatasetColumnDetails[]>([]);
  const [column, setColumn] = useState("");
  const [reportData, setReportData] = useState<any>(null);
  const [loadingDatasets, setLoadingDatasets] = useState(true);
  const [loadingReport, setLoadingReport] = useState(false);
  const [error, setError] = useState("");

  async function reportRequest(url: string) {
    const response = await fetch(url, { cache: "no-store" });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(
        payload?.error || payload?.message || `Report request failed (${response.status}).`
      );
    }
    return payload;
  }

  useEffect(() => {
    let cancelled = false;

    async function loadDatasets() {
      setLoadingDatasets(true);
      setError("");
      try {
        const payload = await reportRequest("/backend/datasets");
        if (!Array.isArray(payload)) throw new Error("Unexpected datasets response.");
        if (!cancelled) {
          setDatasets(payload);
          setDatasetId(payload.length ? String(payload[0].id) : "");
        }
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : "Unable to load datasets.");
      } finally {
        if (!cancelled) setLoadingDatasets(false);
      }
    }

    void loadDatasets();
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (!datasetId) {
      setColumns([]);
      setColumn("");
      return;
    }

    let cancelled = false;
    async function loadColumns() {
      try {
        const payload = await reportRequest(`/backend/datasets/${datasetId}`);
        const nextColumns = Array.isArray(payload?.columns) ? payload.columns : [];
        if (!cancelled) {
          setColumns(nextColumns);
          setColumn(nextColumns[0]?.databaseColumnName || "");
        }
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : "Unable to load dataset columns.");
      }
    }

    void loadColumns();
    return () => { cancelled = true; };
  }, [datasetId]);

  useEffect(() => {
    if (!datasetId || loadingDatasets) {
      setReportData(null);
      return;
    }

    let cancelled = false;
    async function loadReport() {
      setLoadingReport(true);
      setError("");
      setReportData(null);

      try {
        let payload: any;

        if (report === "Data quality summary") {
          payload = await reportRequest(`/backend/datasets/${datasetId}/quality`);
        } else if (report === "Duplicate analysis report") {
          if (!column) {
            setReportData(null);
            return;
          }
          payload = await reportRequest(
            `/backend/datasets/${datasetId}/duplicates/exact?column=${encodeURIComponent(column)}`
          );
        } else if (report === "Merge activity report") {
          payload = await reportRequest(`/backend/datasets/${datasetId}/merge/history`);
        } else {
          payload = datasets;
        }

        if (!cancelled) setReportData(payload);
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : "Unable to generate report.");
      } finally {
        if (!cancelled) setLoadingReport(false);
      }
    }

    void loadReport();
    return () => { cancelled = true; };
  }, [report, datasetId, column, loadingDatasets, datasets]);

  const selectedDataset = datasets.find(item => String(item.id) === datasetId);

  return (
    <>
      <PageHeading
        title="Reports"
        description="Live reports generated from your imported datasets and merge operations."
      />
      <section className="surface full-panel">
        <h2>Report configuration</h2>
        <p className="panel-description">
          Reports load directly from the backend whenever you open this page or change the selected dataset, report type or column.
        </p>
        <div className="form-grid">
          <label>REPORT TYPE
            <select value={report} onChange={e => setReport(e.target.value)}>
              <option>Data quality summary</option>
              <option>Duplicate analysis report</option>
              <option>Dataset import history</option>
              <option>Merge activity report</option>
            </select>
          </label>
          <label>DATASET
            <select value={datasetId} onChange={e => setDatasetId(e.target.value)} disabled={loadingDatasets || datasets.length === 0}>
              {datasets.map(item => (
                <option key={item.id} value={String(item.id)}>
                  {item.datasetName} · {item.totalRows} records
                </option>
              ))}
              {datasets.length === 0 && <option value="">{loadingDatasets ? "Loading datasets..." : "No datasets found"}</option>}
            </select>
          </label>
          {report === "Duplicate analysis report" && (
            <label>COMPARE COLUMN
              <select value={column} onChange={e => setColumn(e.target.value)} disabled={columns.length === 0}>
                {columns.map(item => (
                  <option key={item.databaseColumnName} value={item.databaseColumnName}>
                    {item.excelColumnName} ({item.databaseColumnName})
                  </option>
                ))}
                {columns.length === 0 && <option value="">No columns available</option>}
              </select>
            </label>
          )}
        </div>
        {error && <p className="feedback-message" style={{ color: "#b64b3d" }}>{error}</p>}
      </section>

      <section className="surface full-panel">
        <div className="section-heading">
          <div>
            <h2>{report}</h2>
            <p className="panel-description">
              {selectedDataset ? `${selectedDataset.datasetName} · Current database state` : "Workspace report"}
            </p>
          </div>
          <span className="status-pill ready">LIVE DATABASE RESULTS</span>
        </div>

        {loadingReport && <p className="empty-state">Loading the latest report data...</p>}

        {!loadingReport && reportData && report === "Duplicate analysis report" && (
          <>
            <div className="result-stats">
              <div><span>TOTAL RECORDS</span><strong>{Number(reportData.totalRecords || 0).toLocaleString("en-IN")}</strong></div>
              <div><span>DUPLICATE GROUPS</span><strong>{Number(reportData.duplicateGroups || 0).toLocaleString("en-IN")}</strong></div>
              <div><span>DUPLICATE RECORDS</span><strong>{Number(reportData.duplicateRecords || 0).toLocaleString("en-IN")}</strong></div>
              <div><span>UNIQUE RECORDS</span><strong>{Number(reportData.uniqueRecords || 0).toLocaleString("en-IN")}</strong></div>
            </div>
            <div className="data-table-wrap">
              <table className="data-table">
                <thead><tr><th>MATCHING VALUE</th><th>OCCURRENCES</th></tr></thead>
                <tbody>
                  {(reportData.groups || []).map((group: DuplicateGroup, index: number) => (
                    <tr key={`${group.value}-${index}`}><td>{group.value}</td><td>{group.occurrences}</td></tr>
                  ))}
                </tbody>
              </table>
              {(reportData.groups || []).length === 0 && <p className="empty-state">No active duplicate groups remain for this column.</p>}
            </div>
          </>
        )}

        {!loadingReport && reportData && report === "Data quality summary" && (
          <>
            <div className="result-stats">
              <div><span>OVERALL QUALITY</span><strong>{Number(reportData.overallQualityScore || 0).toFixed(2)}%</strong></div>
              <div><span>TOTAL RECORDS</span><strong>{Number(reportData.totalRecords || 0).toLocaleString("en-IN")}</strong></div>
              <div><span>MISSING VALUES</span><strong>{Number(reportData.totalBlankValues || 0).toLocaleString("en-IN")}</strong></div>
              <div><span>INVALID VALUES</span><strong>{Number(reportData.totalInvalidValues || 0).toLocaleString("en-IN")}</strong></div>
            </div>
          </>
        )}

        {!loadingReport && Array.isArray(reportData) && report === "Merge activity report" && (
          <div className="data-table-wrap">
            <table className="data-table">
              <thead><tr><th>OPERATION ID</th><th>SURVIVOR ID</th><th>STATUS</th><th>CREATED AT</th></tr></thead>
              <tbody>
                {reportData.map((item: MergeHistoryItem) => (
                  <tr key={item.mergeOperationId}>
                    <td>{item.mergeOperationId}</td>
                    <td>{item.survivorRecordId}</td>
                    <td>{item.status}</td>
                    <td>{item.createdAt ? new Date(item.createdAt).toLocaleString("en-IN") : "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {reportData.length === 0 && <p className="empty-state">No merge operations found for this dataset.</p>}
          </div>
        )}

        {!loadingReport && Array.isArray(reportData) && report === "Dataset import history" && (
          <div className="data-table-wrap">
            <table className="data-table">
              <thead><tr><th>DATASET</th><th>FILE</th><th>RECORDS</th><th>IMPORTED AT</th><th>STATUS</th></tr></thead>
              <tbody>
                {reportData.map((item: DatasetApiResponse) => (
                  <tr key={item.id}>
                    <td>{item.datasetName}</td><td>{item.originalFileName}</td>
                    <td>{Number(item.totalRows || 0).toLocaleString("en-IN")}</td>
                    <td>{item.importedAt ? new Date(item.importedAt).toLocaleString("en-IN") : "—"}</td>
                    <td>{item.importStatus}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {!loadingReport && !reportData && !error && !loadingDatasets && (
          <p className="empty-state">Import a dataset to generate a live report.</p>
        )}
      </section>
    </>
  );
}

function SettingsPage() {
  const [threshold, setThreshold] = useState("85");
  const [dbName, setDbName] = useState("dataforge_db");
  return (
    <>
      <PageHeading title="Settings" description="Configure workspace and data processing preferences."/>
      <section className="surface full-panel">
        <div className="settings-section"><Server/><div><h2>Database connection</h2><p>PostgreSQL connection configuration.</p></div></div>
        <div className="form-grid">
          <label>DATABASE TYPE<input value="PostgreSQL" readOnly/></label>
          <label>DATABASE NAME<input value={dbName} onChange={e => setDbName(e.target.value)}/></label>
          <label>CONNECTION STATUS<input value="Backend connection pending" readOnly/></label>
        </div>
        <div className="settings-section"><SlidersHorizontal/><div><h2>Duplicate detection preferences</h2><p>Default similarity threshold for near-match analysis.</p></div></div>
        <div className="form-grid">
          <label>SIMILARITY THRESHOLD (%)<select value={threshold} onChange={e => setThreshold(e.target.value)}><option value="70">70%</option><option value="75">75%</option><option value="80">80%</option><option value="85">85%</option><option value="90">90%</option><option value="95">95%</option></select></label>
        </div>
        <div className="info-strip"><Lock size={17}/><span>Database credentials will be configured securely on the backend, not stored in frontend code.</span></div>
      </section>
    </>
  );
}

export default function Home() {
  const [showSplash, setShowSplash] = useState(true);
  const [activeNav, setActiveNav] = useState<ModuleName>("Overview");
  const [mobileMenu, setMobileMenu] = useState(false);

  useEffect(() => {
    document.title = "AF DataForge";
    const timer = window.setTimeout(() => setShowSplash(false), 2300);
    return () => window.clearTimeout(timer);
  }, []);

  if (showSplash) {
    return (
      <main className="splash">
        <div className="splash-content">
          <BrandMark width={440}/>
          <div className="splash-rule"/>
          <div className="splash-product">AF DATA STUDIO</div>
          <div className="splash-description">INTELLIGENT DATA MANAGEMENT</div>
          <div className="splash-loader"><span/></div>
        </div>
        <div className="splash-footer">A PRODUCT BY ALTIUS FORTIUS</div>
      </main>
    );
  }

  function renderModule() {
    switch (activeNav) {
      case "Overview": return <Overview navigate={setActiveNav}/>;
      case "Import data": return <ImportPage/>;
      case "Data collections": return <CollectionsPage/>;
      case "Data quality": return <QualityPage/>;
      case "Duplicate detection": return <DuplicatePage/>;
      case "Merge records": return <MergePage/>;
      case "Reports": return <ReportsPage/>;
      case "Settings": return <SettingsPage/>;
    }
  }

  return (
    <div className="studio">
      <aside className={`sidebar ${mobileMenu ? "mobile-open" : ""}`}>
        <div className="sidebar-brand">
          <BrandMark width={170}/>
          <button className="mobile-close" onClick={() => setMobileMenu(false)}><X size={19}/></button>
        </div>
        <div className="product-brand"><strong>AF DATA STUDIO</strong><span>INTELLIGENT DATA MANAGEMENT</span></div>
        <div className="sidebar-label">COMMAND</div>
        <nav className="side-nav">
          {navItems.map(({name, icon: Icon}) => (
            <button key={name} onClick={() => {setActiveNav(name);setMobileMenu(false);window.scrollTo({top:0,behavior:"smooth"});}} className={`side-link ${activeNav === name ? "selected" : ""}`}>
              <Icon size={17}/><span>{name}</span>
            </button>
          ))}
        </nav>
        <div className="sidebar-bottom">
          <div className="sidebar-label">DATA CONNECTION</div>
          <div className="connection-card"><Database size={17}/><div><strong>PostgreSQL / Primary</strong><small><i className="green-dot"/> Backend connection pending</small></div></div>
          <div className="sidebar-version">AF DATA STUDIO · V1.0</div>
        </div>
      </aside>

      <main className="main-content">
        <header className="top-header">
          <div className="header-title"><span>WORKSPACE / DATA OPERATIONS</span><strong>{activeNav.toUpperCase()}</strong></div>
          <div className="header-tools">
            <button className="mobile-menu" onClick={() => setMobileMenu(true)}><Menu size={20}/></button>
            <label className="global-search"><Search size={16}/><input placeholder="Search records, datasets, fields..."/></label>
            <button className="header-icon" aria-label="Notifications"><Bell size={18}/><i/></button>
          </div>
        </header>

        <div className="page-content">
          {renderModule()}
          <footer className="app-footer">
            <span>© 2026 ALTIUS FORTIUS</span>
            <span>HIGHER AND STRONGER · AF DATA STUDIO</span>
          </footer>
        </div>
      </main>
    </div>
  );
}
